create transformer on CK.vT
as
begin
    add column Z = 3;
    replace single {X,} with "X = 2,";
end

Test.Text:
    -- SetupConfig: {}
    create view [CK].[vGroup]
    as 
	select  g.GroupId,
			GroupName = g.GroupName,
			UserCount = (select count(*) 
							from CK.tUser u with(nolock) 
							inner join CK.tActorProfile p with(nolock) on p.ActorId = u.UserId
							where p.GroupId = g.GroupId)
		from CK.tGroup g;

Test.Description:
-- In v6.0.0-delta.4 this transformer fails miserably, letting -- -- | | | | select g2.GroupId,/*癃ck-skip㜒select g.GroupId,*/ -- | | | | GroupName = g2.GroupName,/*癃ck-skip㜒GroupName = g.GroupName,*/ -- | | | | UserCount = (select count(*) -- | | | | from CK.tUser u with(nolock) -- | | | | inner join CK.tActorProfile p with(nolock) on p.ActorId = u.UserId -- | | | | where p.GroupId = g2.GroupId/*癃ck-skip㜒where p.GroupId = g.GroupId*/) -- -- With v6.0.0, this works: -- - "add column" (and "add parameters") now reparse any dirty text. -- - The SqlNodeLocation.ChangeNode has been fixed to handle shared/reused nodes by parents. -- create transformer on [CK].[vGroup] as begin
add column ManagerId = ap.ActorId;
inject " join CK.tActorProfile ap on g.GroupId = ap.GroupId and ap.ActorId <> ap.GroupId join CK.tActorProfile ap2 on ap2.ActorId = ap.ActorId join CK.tGroup g2 on ap2.GroupId = g2.GroupId where g.GroupName = 'Manager' and g2.[Status] = 0 " after single {from CK.tGroup g};
replace single {GroupName = g.GroupName,} with "GroupName = g2.GroupName,";
replace single {select g.GroupId,} with "select g2.GroupId,";
replace single {where p.GroupId = g.GroupId} with "where p.GroupId = g2.GroupId"; end
